/** Live owner motor: bounded convergence, queued commits, ordinary keys and physics-observed water leases. */
public final class BotMotor {
    public interface Services {
        Player player();boolean current();boolean crouch();Player target(int id);long loop();
        void orientation(Vector aim);void movement(int flags);void actions(boolean primary,boolean secondary,boolean zoom,boolean hover);
        boolean select(int tool);boolean execute(Action action);int stock(int tool);double nextShot();double fireInterval();
        Cell ray(Vector eye,Vector direction,double distance);boolean drySafe(Vector position);void buriedDeath();
        void stage(BotMotor motor,Action action,double at);
    }
    public static final class Budget {private final Thread owner=Thread.currentThread();private int walls;public final BotLiveSteering.Budget movement=new BotLiveSteering.Budget();public void reset(){owned();walls=0;movement.reset();}private void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Motor budget outside owner");}}
    private final Thread owner=Thread.currentThread();private final Services service;private final BotLiveSteering.World world;private final BotLiveSteering steering;private final Budget budget;private BotProfile profile;private final BotAimMotor aim;private final BotIntentState state;
    private long jumpUntil=-1,jumpRearm=-1,lastJump=-1,primaryUntil=-1;private int burstRemaining,movementFlags;private ActionKind primaryKind=ActionKind.NONE;private boolean primary,secondary,zoom,hover;private double nextFire,nextWallProbe,wadeUntil,landedAt=-Double.MAX_VALUE;private boolean wallClear=true;private Double buriedSince;private Vector buriedAnchor;
    public BotMotor(int id,int generation,BotProfile profile,SourceRandom random,double yaw,Services service,BotLiveSteering.World world,Budget budget){this.profile=Objects.requireNonNull(profile);this.service=Objects.requireNonNull(service);this.world=Objects.requireNonNull(world);this.budget=Objects.requireNonNull(budget);aim=new BotAimMotor(profile,random,yaw);state=new BotIntentState(id,generation);steering=new BotLiveSteering(world,budget.movement);}
    private void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Bot motor outside owner");budget.owned();}
    public void profile(BotProfile value){owned();profile=Objects.requireNonNull(value);aim.profile(value);}
    public BotIntentState state(){owned();return state;}public BotAimMotor.State aim(){owned();return aim.state();}public double wadeObservedUntil(){owned();return wadeUntil;}public double waterLandedAt(){owned();return landedAt;}
    public boolean accept(Intent intent,long map,long mode,long topology,double now){owned();var p=service.player();if(!service.current())return false;int previous=state.lockPlayer();boolean accepted=state.accept(intent,p.lifeId(),map,mode,topology,now);if(accepted&&intent.look()!=null&&intent.look().visible()&&intent.look().targetPlayerId()>=0&&intent.look().targetPlayerId()!=previous){wallClear=true;nextWallProbe=0;burstRemaining=0;aim.overshoot(BotAimMotor.wrap(Math.atan2(intent.look().target().y()-p.eye().y(),intent.look().target().x()-p.eye().x())-aim.state().yaw()));}return accepted;}
    public void clear(){owned();state.clear();steering.clear();jumpUntil=jumpRearm=lastJump=primaryUntil=-1;burstRemaining=0;nextFire=nextWallProbe=wadeUntil=0;landedAt=-Double.MAX_VALUE;wallClear=true;buriedSince=null;buriedAnchor=null;aim.hold();move(0);actions(false,false,false,false);}
    private void move(int flags){if(flags!=movementFlags){movementFlags=flags;service.movement(flags);}}
    private void actions(boolean p,boolean s,boolean z,boolean h){primary=p;secondary=s;zoom=z;hover=h;service.actions(p,s,z,h);}
    private boolean capable(){var p=service.player();if(p.canShoot())return true;boolean stripped=state.suppressWeapons();if(stripped||burstRemaining>0||primaryKind==ActionKind.FIRE||primaryKind==ActionKind.MELEE||BrainInventory.FIREARMS.contains(p.tool())||net.battlespades.combat.CombatCatalog.SPADES.contains(p.tool())){primaryUntil=-1;primaryKind=ActionKind.NONE;actions(false,false,false,hover);}burstRemaining=0;nextFire=0;return false;}
    private BotLiveSteering.Body body(Player p){return new BotLiveSteering.Body(p.id(),p.generation(),p.position(),p.velocity(),p.grounded(),p.wade(),service.crouch(),p.jetpackId());}
    private Vector liveAim(Look look,double now){var target=look.targetPlayerId()<0?null:service.target(look.targetPlayerId());if(target==null||!target.alive()||!target.spawned()||!state.lock(look.targetPlayerId(),target.generation(),now))return look.target();double settle=Math.clamp((now-state.lockStarted())/1.2,0,1),lag=profile.trackingDelay()*(1-.7*settle);return new Vector(target.eye().x()-target.velocity().x()*lag,target.eye().y()-target.velocity().y()*lag,target.eye().z()-target.velocity().z()*lag+look.aimOffsetZ());}
    private double settle(Look look,double now){var target=look.targetPlayerId()<0?null:service.target(look.targetPlayerId());return target!=null&&target.alive()&&target.spawned()&&state.lock(look.targetPlayerId(),target.generation(),now)?Math.clamp((now-state.lockStarted())/1.2,0,1):0;}
    private void look(Vector target,double dt,double noise,String purpose){service.orientation(aim.update(service.player().eye(),target,dt,noise,purpose));}
    public void tick(double now,double dt){
        owned();if(!service.current())return;capable();var p=service.player();state.expire(p.lifeId(),p.alive()&&p.spawned(),now);observePhysics(now);recoverBuried(now);p=service.player();var intent=state.intent();
        if(!p.alive()||!p.spawned()||intent==null||intent.expiresAt()<=now){jumpUntil=jumpRearm=-1;var pending=state.pending();var goal=pending==null?null:pending.position()!=null?pending.position():state.pendingLook();if(goal!=null){look(goal,dt,1,pending.position()!=null?"precise":"combat");tryPending(now);}else aim.hold();move(0);actions(p.alive()&&p.spawned()&&service.loop()<=primaryUntil,state.pending()!=null&&state.pendingSecondary(),state.pending()!=null&&state.pendingZoom(),false);return;}
        if(intent.toolId()>=0&&p.tool()!=intent.toolId())service.select(intent.toolId());var action=state.takeAction();if(action!=null)execute(action,now);p=service.player();var liveBody=body(p);var travel=BotLiveSteering.travelDirection(liveBody,intent);var pending=state.pending();
        if(pending!=null&&pending.position()!=null)look(pending.position(),dt,1,"precise");else if(intent.look()!=null){Vector point;double settling;if(BotLiveSteering.travelTarget(intent)&&!intent.look().glance()){double length=Math.hypot(travel.x(),travel.y()),dx=length>1e-6?travel.x():Math.cos(aim.state().yaw()),dy=length>1e-6?travel.y():Math.sin(aim.state().yaw());if(length<=1e-6)length=1;var rest=intent.movement().gazeWaypoint();if(rest!=null&&flat(rest,p.eye())>2){dx=rest.x()-p.eye().x();dy=rest.y()-p.eye().y();length=Math.hypot(dx,dy);}point=new Vector(p.eye().x()+dx/length*6,p.eye().y()+dy/length*6,p.eye().z());settling=0;}else{point=liveAim(intent.look(),now);settling=settle(intent.look(),now);}String purpose=BotLiveSteering.travelTarget(intent)&&!intent.look().glance()?BotLiveSteering.travelPurpose(intent):intent.look().visible()?"combat":intent.movement().affordance()==Affordance.BREACH||intent.action().position()!=null?"precise":"focus";look(point,dt,1/(1+2*settling*(.35+.65*profile.skill())),purpose);}else if(state.pendingLook()!=null)look(state.pendingLook(),dt,1,"combat");else aim.hold();
        actions(primary,intent.secondaryFire(),intent.zoom(),hover);tryPending(now);p=service.player();liveBody=body(p);int drop=Math.clamp(intent.movement().walkDrop(),1,4);var affordance=intent.movement().affordance();var direction=steering.direction(liveBody,travel,affordance,drop,now);boolean completed=intent.createdAt()<=landedAt&&(affordance==Affordance.SWIM||affordance==Affordance.JUMP),over=p.position().z()>=233.75&&world.water((int)Math.floor(p.position().x()),(int)Math.floor(p.position().y()));
        if((p.wade()||over)&&Math.hypot(direction.x(),direction.y())<=.1&&!Set.of(Affordance.SWIM,Affordance.BUILD_STEP,Affordance.JUMP).contains(affordance)&&!intent.debugRole().startsWith("water_")){var fallback=Math.hypot(intent.movement().direction().x(),intent.movement().direction().y())>1e-6?intent.movement().direction():intent.debugGoal()!=null?new Vector(intent.debugGoal().x()-p.position().x(),intent.debugGoal().y()-p.position().y(),0):new Vector(p.orientation().x(),p.orientation().y(),0);double length=Math.hypot(fallback.x(),fallback.y());if(length>1e-6){fallback=new Vector(fallback.x()/length,fallback.y()/length,0);direction=steering.direction(liveBody,fallback,Affordance.SWIM,drop,now);if(Math.hypot(direction.x(),direction.y())>.1)affordance=Affordance.SWIM;else{direction=steering.direction(liveBody,fallback,Affordance.JUMP,drop,now);if(Math.hypot(direction.x(),direction.y())>.1)affordance=Affordance.JUMP;}}}
        double length=Math.hypot(p.orientation().x(),p.orientation().y()),fx=length>1e-6?p.orientation().x()/length:Math.cos(aim.state().yaw()),fy=length>1e-6?p.orientation().y()/length:Math.sin(aim.state().yaw());boolean pack=affordance==Affordance.JETPACK&&intent.movement().jetpackThrust()&&p.jetpackId()>0&&p.jetpackFuel()>0,hoverPack=p.jetpackId()==69,jump=!completed&&(intent.movement().jump()||affordance==Affordance.JUMP),ascent=!completed&&p.wade()&&(jump||affordance==Affordance.SWIM||affordance==Affordance.BREACH)&&affordance!=Affordance.JUMP;long loop=service.loop();if(ascent)jumpUntil=jumpRearm=-1;else if(jump&&intent.frameId()!=lastJump&&loop>=jumpRearm){lastJump=intent.frameId();jumpUntil=loop+2;jumpRearm=jumpUntil+2;}var keys=aim.keys(direction.x()*fx+direction.y()*fy,-direction.x()*fy+direction.y()*fx);boolean held=!completed&&(pack&&!hoverPack||ascent||loop<=jumpUntil);int flags=(keys.forward()>0?1:0)|(keys.forward()<0?2:0)|(keys.side()<0?4:0)|(keys.side()>0?8:0)|(held?16:0)|(intent.movement().crouch()||affordance==Affordance.CROUCH?32:0)|(intent.movement().sneak()?64:0)|(intent.movement().sprint()&&Math.hypot(direction.x(),direction.y())>.1?128:0);move(completed?0:flags);if(completed)brake(now);actions(loop<=primaryUntil,intent.secondaryFire(),intent.zoom(),pack&&hoverPack);
    }
    private boolean execute(Action action,double now){var p=service.player();boolean accepted=state.commit(p.lifeId(),action,()->service.execute(action));state.result(action,accepted,now,action.kind()==ActionKind.DEPLOY&&service.stock(action.toolId())<=0);return accepted;}
    private void tryPending(double now){capable();var action=state.pending();if(action==null)return;var p=service.player();state.expire(p.lifeId(),p.alive()&&p.spawned(),now);if(state.pending()==null)return;if(action.kind()==ActionKind.FIRE&&now<nextFire)return;double wait=service.nextShot()-1./60-now;if(action.kind()==ActionKind.MELEE&&wait>0){if(wait>.25)state.clearPending();return;}Vector reference=action.position();boolean visible=true;if(reference==null){var intent=state.intent();if(intent!=null&&intent.look()!=null&&intent.expiresAt()>now){reference=liveAim(intent.look(),now);visible=intent.look().visible();}else{reference=state.pendingLook();visible=state.pendingVisible();}}if((action.kind()==ActionKind.FIRE||action.kind()==ActionKind.ORIENTED)&&!visible)return;
        if(reference!=null){double distance=distance(reference,p.eye());if(distance>1e-6){var delta=new Vector(reference.x()-p.eye().x(),reference.y()-p.eye().y(),reference.z()-p.eye().z());double cosine=(p.orientation().x()*delta.x()+p.orientation().y()*delta.y()+p.orientation().z()*delta.z())/distance;if(cosine<BotIntentState.facingThreshold(profile,action,distance))return;if(action.kind()==ActionKind.MELEE&&action.position()!=null&&state.intent()!=null&&state.intent().movement().affordance()==Affordance.BREACH){var expected=new Cell((int)Math.floor(action.position().x()),(int)Math.floor(action.position().y()),(int)Math.floor(action.position().z()));if(!expected.equals(service.ray(p.eye(),p.orientation(),3)))return;}if((action.kind()==ActionKind.FIRE||action.kind()==ActionKind.ORIENTED)&&!lane(p,delta,distance,now))return;}}service.stage(this,action,now);
    }
    private boolean lane(Player p,Vector delta,double distance,double now){if(distance>2&&now>=nextWallProbe&&budget.walls<4){budget.walls++;nextWallProbe=now+.1;var unit=new Vector(delta.x()/distance,delta.y()/distance,delta.z()/distance);wallClear=service.ray(p.eye(),unit,Math.min(distance-1,128))==null;}return wallClear;}
    /** Called only when a director drains its bounded queue; every captured identity is revalidated. */
    public boolean commit(Action action,double now){owned();var p=service.player();if(!service.current()||state.pending()!=action||!p.alive()||!p.spawned()||state.pendingLife()>=0&&state.pendingLife()!=p.lifeId())return false;if((action.kind()==ActionKind.FIRE||action.kind()==ActionKind.MELEE)&&!capable())return false;boolean accepted=execute(action,now);if(accepted&&action.kind()==ActionKind.FIRE)aim.recoil(service.player().tool());if(accepted&&action.kind()==ActionKind.FIRE&&state.locked(now)){double interval=Math.max(service.fireInterval(),1./30);if(action.burst()>0){if(burstRemaining<=0)burstRemaining=action.burst();burstRemaining--;if(burstRemaining<=0)interval+=Math.max(0,action.burstPause());}nextFire=now+interval;}else state.clearPending();if(accepted){primaryUntil=Math.max(primaryUntil,service.loop()+2);primaryKind=action.kind();}return true;}
    public void observePhysics(double now){owned();if(!service.current())return;capable();var p=service.player();if(p.wade()){wadeUntil=Math.max(wadeUntil,now+.5);return;}if(wadeUntil>now&&p.grounded()&&service.drySafe(p.position())){wadeUntil=0;landedAt=now;var i=state.intent();if(i!=null&&(i.movement().affordance()==Affordance.SWIM||i.movement().affordance()==Affordance.JUMP)){jumpUntil=jumpRearm=-1;lastJump=i.frameId();move(0);}}brake(now);}
    private void brake(double now){var i=state.intent();if(i==null||i.createdAt()>landedAt||i.movement().affordance()!=Affordance.SWIM&&i.movement().affordance()!=Affordance.JUMP)return;var p=service.player();jumpUntil=jumpRearm=-1;double speed=Math.hypot(p.velocity().x(),p.velocity().y());if(i.expiresAt()<=now||!p.alive()||!p.spawned()||!p.grounded()||p.wade()||speed<=.015){move(0);return;}double length=Math.hypot(p.orientation().x(),p.orientation().y()),ox=length>1e-6?p.orientation().x()/length:Math.cos(aim.state().yaw()),oy=length>1e-6?p.orientation().y()/length:Math.sin(aim.state().yaw()),dx=-p.velocity().x()/speed,dy=-p.velocity().y()/speed,forward=dx*ox+dy*oy,side=-dx*oy+dy*ox;move((forward>.25?1:0)|(forward<-.25?2:0)|(side<-.25?4:0)|(side>.25?8:0));}
    private void recoverBuried(double now){var p=service.player();boolean buried=p.alive()&&p.spawned()&&p.position().z()>=237.9&&world.solid((int)Math.floor(p.position().x()),(int)Math.floor(p.position().y()),239);if(!buried){buriedSince=null;buriedAnchor=null;return;}if(buriedSince==null||buriedAnchor==null||flat(p.position(),buriedAnchor)>=2){buriedSince=now;buriedAnchor=p.position();}else if(now-buriedSince>=6){buriedSince=null;service.buriedDeath();}}
}
